"""Decorators instrumenting TTS engine connect and disconnect."""

from rasa.tracing.voice.metrics import VoiceComponent
from rasa.tracing.voice.recorders.connection import (
    observed_connect,
    observed_disconnect,
)
from rasa.tracing.voice.recorders.tts.span_attributes import (
    connect_attributes,
    engine_attributes,
)
from rasa.tracing.voice.shared import semconv

# Apply to TTSEngine.connect and to every provider override of connect().
traced_tts_connect = observed_connect(
    semconv.SPAN_NAME_CONNECT_TTS,
    connect_attributes,
    VoiceComponent.TTS,
)

# Apply to TTSEngine.close_connection and to every provider override of it.
traced_tts_disconnect = observed_disconnect(
    semconv.SPAN_NAME_DISCONNECT_TTS,
    engine_attributes,
    VoiceComponent.TTS,
)
